INSERT INTO `admin_notepad` VALUES
(1,'claude --permission-mode bypassPermissions\nплитка - список запоминать положение\nпри загрузке json добавлять только то, чего нет, не делать дубли\nна линукс не отрисовываются иконки на ссылках , страницах\nМодель не гарантирует сохранение контекста между сессиями, поэтому память надёжнее держать в файлах. RULES-md или AGENTS-md с архитектурой и принципами, отдельные документы на крупные модули, CHANGELOG-md с историей, TODO-md с незакрытыми хвостами. Такой документ окупается на первом же новом чате.\n\nв панели управления там где файлы сервера исправь вид папок\n\nVercel\nCoolify\nCloudflare\n\n\n\n\n\n\n\n\n','2026-08-24 15:58:24');
